window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-17691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσθενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6452 na letra ε · nº geral 17691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forte; robusto; vigoroso. 〈εὖ, σθένος〉</p></section></article>\n<article id=\"entry-dgp-17692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσκαρθμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6453 na letra ε · nº geral 17692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que salta bem; ágil; rápido. 〈εὖ, σκαίρω〉</p></section></article>\n<article id=\"entry-dgp-17693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσκέπαστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6454 na letra ε · nº geral 17693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que oferece bom abrigo; acolhedor. 〈εὖ, σκεπάζω〉</p></section></article>\n<article id=\"entry-dgp-17694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσκευέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6455 na letra ε · nº geral 17694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser bem equipado. 〈εὖ, σκεῦος〉</p></section></article>\n<article id=\"entry-dgp-17695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσκίαστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6456 na letra ε · nº geral 17695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem abrigado. 〈εὖ, σκιάζω〉</p></section></article>\n<article id=\"entry-dgp-17696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσκιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6457 na letra ε · nº geral 17696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem sombreado. 〈εὖ, σκιά〉</p></section></article>\n<article id=\"entry-dgp-17697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσκοπος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6458 na letra ε · nº geral 17697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰσκοπος, ος, ον 1 que enxerga de longe ou longe 2 que mira bem; que atinge o alvo 3 bem na vista; visível. 〈εὖ, σκοπέω〉</p></section></article>\n<article id=\"entry-dgp-17698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσοια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6459 na letra ε · nº geral 17698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saúde; prosperidade. 〈εὖ, σόος〉</p></section></article>\n<article id=\"entry-dgp-17699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσπλαγχνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6460 na letra ε · nº geral 17699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. de entranhas sadias 2 bíbl. misericordioso; compassivo. 〈εὖ, σπλάγχνον〉</p></section></article>\n<article id=\"entry-dgp-17700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσπορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6461 na letra ε · nº geral 17700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem semeado; fértil. 〈εὖ, σπείρω〉</p></section></article>\n<article id=\"entry-dgp-17701\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐΰσσελμος</h1><div class=\"entry-meta\"><span>DGP · ordem 6462 na letra ε · nº geral 17701</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = εὔσελμος.</p></section></article>\n<article id=\"entry-dgp-17702\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστάθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6463 na letra ε · nº geral 17702</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">firmeza; estabilidade; consistência; equilíbrio do corpo e da inteligência; tranqüilidade. 〈εὐσταθής〉</p></section></article>\n<article id=\"entry-dgp-17703\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσταθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6464 na letra ε · nº geral 17703</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser firme, consistente, bem equilibrado 2 ser calmo. 〈εὐσταθής〉</p></section></article>\n<article id=\"entry-dgp-17704\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσταθής,</h1><div class=\"entry-meta\"><span>DGP · ordem 6465 na letra ε · nº geral 17704</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋσταθής, ής, ές 1 bem estável; firme; fixo; sólido 2 são; sadio (corpo) 3 são de corpo e alma; de caráter calmo ou sereno; tranqüilo. 〈εὖ, ἵστημι〉</p></section></article>\n<article id=\"entry-dgp-17705\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσταλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6466 na letra ε · nº geral 17705</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem ou convenientemente equipado 2 cujo armamento é bem proporcionado ou que não sobrecarrega; ligeiro; alerta (soldado) 3 simples; leve; de fácil manejo (equipamento) 4 de postura correta (pessoa) 5 fácil; cômodo. 〈εὖ, στέλλω〉</p></section></article>\n<article id=\"entry-dgp-17706\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσταλία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6467 na letra ε · nº geral 17706</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agilidade; ligeireza. 〈εὐσταλής〉</p></section></article>\n<article id=\"entry-dgp-17707\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσταλῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6468 na letra ε · nº geral 17707</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com agilidade; prontamente.</p></section></article>\n<article id=\"entry-dgp-17708\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστέφανος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6469 na letra ε · nº geral 17708</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋστέφανος, ος, ον 1 coroado de flores; ornado de guirlandas 2 rodeado de torres e de trincheiras. 〈εὖ, στέφανος〉</p></section></article>\n<article id=\"entry-dgp-17709\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔστολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6470 na letra ε · nº geral 17709</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem equipado 2 ágil; ligeiro. 〈εὖ, στέλλω〉</p></section></article>\n<article id=\"entry-dgp-17710\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστόμαχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6471 na letra ε · nº geral 17710</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agradável para o estômago; apetitoso 2 salutar; digestivo. 〈εὖ, στόμαχος〉</p></section></article>\n<article id=\"entry-dgp-17711\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστομάχως</h1><div class=\"entry-meta\"><span>DGP · ordem 6472 na letra ε · nº geral 17711</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com bom estômago; tranqüilamente.</p></section></article>\n<article id=\"entry-dgp-17712\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6473 na letra ε · nº geral 17712</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cantar ou falar agradavelmente 2 pronunciar palavras de bom agouro. 〈εὔστομος〉</p></section></article>\n<article id=\"entry-dgp-17713\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστομία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6474 na letra ε · nº geral 17713</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 boa pronúncia ou pronúncia agradável 2 elocução agradável ou graciosa; eufonia 3 doçura do canto. 〈εὔστομος〉</p></section></article>\n<article id=\"entry-dgp-17714\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔστομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6475 na letra ε · nº geral 17714</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cuja boca é dócil ao freio 2 de grande abertura ou de amplas bordas (taça) 3 que fala bem 4 que canta bem (pássaro) 5 que pronuncia palavras de bom agouro 6 que guarda silêncio religioso: εὔστομ᾽ ἔχε sóf. silêncio!, περὶ τούτων εὔστομα κείσθω her. que sobre isso se mantenha um silêncio religioso 7 agradável ao paladar 8 que torna eloqüente. 〈εὖ, στόμα〉</p></section></article>\n<article id=\"entry-dgp-17715\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστόμως</h1><div class=\"entry-meta\"><span>DGP · ordem 6476 na letra ε · nº geral 17715</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com voz agradável ou melodiosa 2 em linguagem clara.</p></section></article>\n<article id=\"entry-dgp-17716\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστοχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6477 na letra ε · nº geral 17716</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 visar bem; atingir o alvo 2 atingir, gen. 3 raciocinar ou adivinhar com acerto. 〈εὔστοχος〉</p></section></article>\n<article id=\"entry-dgp-17717\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστοχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6478 na letra ε · nº geral 17717</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 habilidade em visar, em atingir o alvo; boa mira 2 habilidade de aproveitar a ocasião; sagacidade. 〈εὔστοχος〉</p></section></article>\n<article id=\"entry-dgp-17718\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔστοχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6479 na letra ε · nº geral 17718</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hábil em visar, em atingir o alvo 2 que atinge o alvo 3 hábil em raciocinar ou em adivinhar com acerto; sagaz ♦ εὔστοχα adv. 4 atingindo o alvo com boa mira. 〈εὖ, στοχάζομαι〉</p></section></article>\n<article id=\"entry-dgp-17719\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστόχως</h1><div class=\"entry-meta\"><span>DGP · ordem 6480 na letra ε · nº geral 17719</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. direto ao alvo; diretamente; com justeza; de boa mira.</p></section></article>\n<article id=\"entry-dgp-17720\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔστρεπτος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6481 na letra ε · nº geral 17720</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰστρεπτος, ος, ον bem torcido; bem torneado. 〈εὖ, στρέφω〉</p></section></article>\n<article id=\"entry-dgp-17721\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστρεφής,</h1><div class=\"entry-meta\"><span>DGP · ordem 6482 na letra ε · nº geral 17721</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋστρεφής, ής, ές = εὔστρεπτος.</p></section></article>\n<article id=\"entry-dgp-17722\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐστροφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6483 na letra ε · nº geral 17722</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">facilidade de voltar-se em todos os sentidos; flexibilidade; versatilidade. 〈εὔστροφος〉</p></section></article>\n<article id=\"entry-dgp-17723\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔστροφος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6484 na letra ε · nº geral 17723</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰστροφος, ος, ον 1 bem torneado 2 que gira facilmente em todos os sentidos; flexível; versátil 3 manejável. 〈εὖ, στρέφω〉</p></section></article>\n<article id=\"entry-dgp-17724\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔστυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6485 na letra ε · nº geral 17724</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de colunas bem dispostas. 〈εὖ, στῦλος〉</p></section></article>\n<article id=\"entry-dgp-17725\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυκοφάντητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6486 na letra ε · nº geral 17725</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a quem se pode caluniar facilmente; exposto à calúnia. 〈εὖ, συκοφαντέω〉</p></section></article>\n<article id=\"entry-dgp-17726\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυλλόγιστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6487 na letra ε · nº geral 17726</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se presta ao raciocínio, ao silogismo 2 fácil de calcular. 〈εὖ, συλλογίζομαι〉</p></section></article>\n<article id=\"entry-dgp-17727\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσύμβλητος</h1><div class=\"entry-meta\"><span>DGP · ordem 6488 na letra ε · nº geral 17727</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e εὐξύμβλητος, ος, ον fácil de conjeturar, de captar, de adivinhar. 〈εὖ, συμβάλλω〉</p></section></article>\n<article id=\"entry-dgp-17728\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσύμβολος</h1><div class=\"entry-meta\"><span>DGP · ordem 6489 na letra ε · nº geral 17728</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e εὐξύμβολος, ος, ον 1 fácil de conjeturar; de significação clara 2 de contato fácil; acessível 3 correto; honesto; leal 4 de bom agouro. 〈εὖ, συμβάλλω〉</p></section></article>\n<article id=\"entry-dgp-17729\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυνάλλακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6490 na letra ε · nº geral 17729</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de fácil trato; afável 2 que se presta a, πρός e ac. 〈εὖ, συναλλάσσω〉</p></section></article>\n<article id=\"entry-dgp-17730\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυνείδητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6491 na letra ε · nº geral 17730</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cuja consciência é pura. 〈εὖ, σύ­νοιδα〉</p></section></article>\n<article id=\"entry-dgp-17731\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυνεσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6492 na letra ε · nº geral 17731</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inteligência viva; perspicácia. 〈εὐσύ­νετος〉</p></section></article>\n<article id=\"entry-dgp-17732\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσύνετος</h1><div class=\"entry-meta\"><span>DGP · ordem 6493 na letra ε · nº geral 17732</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e εὐξύνετος, ος, ον 1 que compreende rapidamente; perspicaz; inteligente 2 fácil de compreender. 〈εὖ, συνίημι〉</p></section></article>\n<article id=\"entry-dgp-17733\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυνέτως</h1><div class=\"entry-meta\"><span>DGP · ordem 6494 na letra ε · nº geral 17733</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. só comp. át. εὐξυνετώτερον com mais inteligência.</p></section></article>\n<article id=\"entry-dgp-17734\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσυνθετέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6495 na letra ε · nº geral 17734</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser fiel a uma convenção, a um tratado. 〈εὐσύνθετος〉</p></section></article>\n<article id=\"entry-dgp-17735\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσύνθετος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6496 na letra ε · nº geral 17735</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem composto. 〈εὖ, συντίθημι〉</p></section></article>\n<article id=\"entry-dgp-17736\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσύνοπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6497 na letra ε · nº geral 17736</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de perceber num relance de olhos. 〈εὖ, συνοράω〉</p></section></article>\n<article id=\"entry-dgp-17737\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσχημονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6498 na letra ε · nº geral 17737</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter ou assumir uma postura digna, apropriada; comportar-se bem. 〈εὐσχήμων〉</p></section></article>\n<article id=\"entry-dgp-17738\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσχημόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 6499 na letra ε · nº geral 17738</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com postura decente ou digna; honradamente; apropriadamente.</p></section></article>\n<article id=\"entry-dgp-17739\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσχημοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6500 na letra ε · nº geral 17739</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">boa aparência; decoro; compostura. 〈εὐσχήμων〉</p></section></article>\n<article id=\"entry-dgp-17740\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσχήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6501 na letra ε · nº geral 17740</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 de boa aparência; decente; respeitável (na aparência) 2 distinto; notório; honrado 3 conveniente; oportuno (coisa, ação) ♦ τὸ εὔσχημον 4 conveniência. 〈εὖ, σχῆμα〉</p></section></article>\n<article id=\"entry-dgp-17741\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσχήμως</h1><div class=\"entry-meta\"><span>DGP · ordem 6502 na letra ε · nº geral 17741</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = εὐσχημόνως.</p></section></article>\n<article id=\"entry-dgp-17742\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσχολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6503 na letra ε · nº geral 17742</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter tempo livre para, gen. 〈εὔσχολος〉</p></section></article>\n<article id=\"entry-dgp-17743\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσχολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6504 na letra ε · nº geral 17743</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem tempo livre; desocupado. 〈εὖ, σχολή〉</p></section></article>\n<article id=\"entry-dgp-17744\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσωματέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6505 na letra ε · nº geral 17744</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estar em boa forma física; ser forte, robusto. 〈εὖ, σῶμα〉</p></section></article>\n<article id=\"entry-dgp-17745\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτακής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6506 na letra ε · nº geral 17745</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de cozinhar; tenro. 〈εὖ, τήκω〉</p></section></article>\n<article id=\"entry-dgp-17746\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6507 na letra ε · nº geral 17746</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 observar a disciplina; ser disciplinado; ser obediente 2 cumprir seu dever. 〈εὔτακτος〉</p></section></article>\n<article id=\"entry-dgp-17747\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6508 na letra ε · nº geral 17747</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem organizado; em ordem 2 disciplinado; moderado. 〈εὖ, τάσσω〉</p></section></article>\n<article id=\"entry-dgp-17748\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτάκτως</h1><div class=\"entry-meta\"><span>DGP · ordem 6509 na letra ε · nº geral 17748</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em boa ordem 2 com obediência; disciplinadamente.</p></section></article>\n<article id=\"entry-dgp-17749\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐταξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6510 na letra ε · nº geral 17749</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disposição regular (de pedras); bom arranjo 2 bom estado; boa condição (da arma, do cavalo) 3 boa ordem; disciplina 4 justa medida; moderação; temperança 5 Filos. julgamento prático, oportuno. 〈εὔτακτος〉</p></section></article>\n<article id=\"entry-dgp-17750\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτάρακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6511 na letra ε · nº geral 17750</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de perturbar. 〈εὖ, ταράσσω〉</p></section></article>\n<article id=\"entry-dgp-17751\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὖτε</h1><div class=\"entry-meta\"><span>DGP · ordem 6512 na letra ε · nº geral 17751</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. 1 (tempo) quando, com ind., com ἄν e subj., ou com opt. 2 (causa) já que 3 (comp.) assim como; do mesmo modo que.</p></section></article>\n<article id=\"entry-dgp-17752\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτείχεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6513 na letra ε · nº geral 17752</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de boas ou sólidas muralhas; bem fortificado. 〈εὖ, τεῖχος〉</p></section></article>\n<article id=\"entry-dgp-17753\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτειχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6514 na letra ε · nº geral 17753</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐτείχεος.</p></section></article>\n<article id=\"entry-dgp-17754\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτεκνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6515 na letra ε · nº geral 17754</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter boa e bela prole. 〈εὔτεκνος〉</p></section></article>\n<article id=\"entry-dgp-17755\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτεκνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6516 na letra ε · nº geral 17755</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o ter bela prole. 〈εὔτεκνος〉</p></section></article>\n<article id=\"entry-dgp-17756\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτεκνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6517 na letra ε · nº geral 17756</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem muitos filhos 2 fértil (terra) 3 que promete filhos (oráculo) 4 atencioso com os filhos. 〈εὖ, τέκνον〉</p></section></article>\n<article id=\"entry-dgp-17757\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτέλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6518 na letra ε · nº geral 17757</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 valor baixo; preço vil (de objeto) 2 parcimônia; frugalidade; economia 3 mesquinhez 4 baixeza; vulgaridade. 〈εὐτελής〉</p></section></article>\n<article id=\"entry-dgp-17758\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτελής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6519 na letra ε · nº geral 17758</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de baixo preço; barato 2 sem valor; baixo; vil 3 modesto; frugal 4 comum; vulgar. 〈εὖ, τέλος〉</p></section></article>\n<article id=\"entry-dgp-17759\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτελίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 6520 na letra ε · nº geral 17759</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer pouco caso de; baratear; depreciar, ac. 〈εὐτελής〉</p></section></article>\n<article id=\"entry-dgp-17760\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτελῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6521 na letra ε · nº geral 17760</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com pouca despesa; com simplicidade.</p></section></article>\n<article id=\"entry-dgp-17761\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐτέρπη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6522 na letra ε · nº geral 17761</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Euterpe, Musa da dança. 〈εὖ, τέρπω〉</p></section></article>\n<article id=\"entry-dgp-17762\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτεχνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6523 na letra ε · nº geral 17762</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habilidade; destreza. 〈εὔτεχνος〉</p></section></article>\n<article id=\"entry-dgp-17763\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτλήμων,</h1><div class=\"entry-meta\"><span>DGP · ordem 6524 na letra ε · nº geral 17763</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. εὐτλάμων, ων, ον gen. ονος que suporta bem; corajoso. 〈εὖ, τλήμων〉</p></section></article>\n<article id=\"entry-dgp-17764\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐΰτμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6525 na letra ε · nº geral 17764</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem cortado. 〈εὖ, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-17765\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6526 na letra ε · nº geral 17765</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parir com felicidade ou facilmente 2 (planta, animal) proliferar. 〈εὔτοκος〉</p></section></article>\n<article id=\"entry-dgp-17766\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτοκία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6527 na letra ε · nº geral 17766</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parto bem sucedido ou fértil 2 fecundidade; proliferação. 〈εὔτοκος〉</p></section></article>\n<article id=\"entry-dgp-17767\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτοκος</h1><div class=\"entry-meta\"><span>DGP · ordem 6528 na letra ε · nº geral 17767</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) que pare com felicidade ou com facilidade; fecundo. 〈εὖ, τίκτω〉</p></section></article>\n<article id=\"entry-dgp-17768\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτολμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6529 na letra ε · nº geral 17768</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ousadia; confiança; coragem. 〈εὔ­τολ­μος〉</p></section></article>\n<article id=\"entry-dgp-17769\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτολμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6530 na letra ε · nº geral 17769</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de ousadia; audaz; corajoso. 〈εὖ, τόλμα〉</p></section></article>\n<article id=\"entry-dgp-17770\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτόλμως</h1><div class=\"entry-meta\"><span>DGP · ordem 6531 na letra ε · nº geral 17770</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com ousadia; corajosamente.</p></section></article>\n<article id=\"entry-dgp-17771\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6532 na letra ε · nº geral 17771</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter força; ter energia para algo, εἰς e ac.; ter a força ou a capacidade de, inf. 〈εὔτονος〉</p></section></article>\n<article id=\"entry-dgp-17772\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6533 na letra ε · nº geral 17772</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forte tensão; esforço sustentado; vigor. 〈εὔτονος〉</p></section></article>\n<article id=\"entry-dgp-17773\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6534 na letra ε · nº geral 17773</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem esticado; bem tenso 2 forte; vigoroso. 〈εὖ, τείνω〉</p></section></article>\n<article id=\"entry-dgp-17774\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 6535 na letra ε · nº geral 17774</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com tensão; com força; vigorosamente 2 veementemente.</p></section></article>\n<article id=\"entry-dgp-17775\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτράπεζος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6536 na letra ε · nº geral 17775</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cuja mesa é bem servida 2 hospitaleiro 3 refinado; caro (alimento) 4 bom para servir à mesa. 〈εὖ, τράπεζα〉</p></section></article>\n<article id=\"entry-dgp-17776\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτραπελία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6537 na letra ε · nº geral 17776</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disposição para gracejar agradavelmente; bom humor 2 gracejo amável e espirituoso 3 bíbl. gracejo de mau gosto; caçoada. 〈εὐτράπελος〉</p></section></article>\n<article id=\"entry-dgp-17777\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτράπελος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6538 na letra ε · nº geral 17777</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se volta facilmente; flexível; ágil 2 versátil 3 pronto para a resposta; arguto 4 de humor agradável; espirituoso 5 zombeteiro; gozador; εὐτράπελόν ἐστιν com inf. é ridículo. 〈εὖ, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-17778\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτραπέλως</h1><div class=\"entry-meta\"><span>DGP · ordem 6539 na letra ε · nº geral 17778</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com flexibilidade; com versatilidade; com tato. 〈εὐτράπελος〉</p></section></article>\n<article id=\"entry-dgp-17779\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτραφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6540 na letra ε · nº geral 17779</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem nutrido; bem desenvolvido; gordo 2 nutritivo. 〈εὖ, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-17780\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτρεπής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6541 na letra ε · nº geral 17780</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se pode rodar ou pôr em movimento 2 pronto; disponível. 〈εὖ, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-17781\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτρεπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 6542 na letra ε · nº geral 17781</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deixar pronto; preparar; dispor ♦ méd. 2 preparar para uso pessoal; dispor ou preparar para si; aprontar 3 pôr-se de acordo com; concordar com alguém, ac. 4 cativar. 〈εὐτρεπής〉</p></section></article>\n<article id=\"entry-dgp-17782\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτρεπιστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 6543 na letra ε · nº geral 17782</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de εὐτρεπίζω.</p></section></article>\n<article id=\"entry-dgp-17783\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτρεπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6544 na letra ε · nº geral 17783</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se faz virar facilmente; versátil; flexível 2 inclinado a algo, πρός e ac.: εὔτ. πρὸς μεταβολάς plut. inclinado a mudar ♦ τὸ εὔτρεπτον 3 facilidade de mudar; mobilidade; inconstância (de caráter). 〈εὖ, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-17784\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτρεπτῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6545 na letra ε · nº geral 17784</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com boa disposição; εὐτ. ἔχειν ser favorável; estar pronto; estar disponível.</p></section></article>\n<article id=\"entry-dgp-17785\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτρεφής,</h1><div class=\"entry-meta\"><span>DGP · ordem 6546 na letra ε · nº geral 17785</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋτρεφής, ής, ές bem nutrido; gordo; forte. 〈εὖ, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-17786\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτρητος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6547 na letra ε · nº geral 17786</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. ἐΰτρητος, ος, ον bem perfurado; perfurado com arte. 〈εὖ, τιτράω〉</p></section></article>\n<article id=\"entry-dgp-17787\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτριχος</h1><div class=\"entry-meta\"><span>DGP · ordem 6548 na letra ε · nº geral 17787</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de εὔθριξ.</p></section></article>\n<article id=\"entry-dgp-17788\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐτροπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6549 na letra ε · nº geral 17788</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">versatilidade; boa disposição. 〈εὔτροπος〉</p></section></article>\n<article id=\"entry-dgp-17789\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτροπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6550 na letra ε · nº geral 17789</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">versátil. 〈εὖ, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-17790\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔτροχος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6551 na letra ε · nº geral 17790</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰτροχος, ος, ον 1 de belas rodas ou de rodas ágeis 2 redondo; circular 3 rápido; veloz; ligeiro. 〈εὖ, τρέχω〉</p></section></article>\n";
